INSERT INTO "services" ("id", "slug", "name", "summary", "heroTitle", "description", "bodyHeading", "bodyText", "sections", "iconKey", "seoTitle", "seoDescription", "showOnHomepage", "showInFooter", "isPublished", "sortOrder", "updatedAt") VALUES ('service-website-design-development', 'website-design-development', 'Website Development', 'A professional, secure online presence — from a simple starter site to a full digital platform.', 'Website Development', 'A professional, secure online presence — from a simple starter site to a full digital platform.', 'Elevate Your Digital Presence', 'In today''s fast-paced digital landscape, an off-the-shelf solution simply doesn''t cut it. We engineer custom web platforms tailored explicitly to your operational workflows and customer journeys.', '[{"title":"Custom Web Applications","description":"Tailor-made web apps built with modern frameworks focused on scalability."},{"title":"E-Commerce Solutions","description":"Robust platforms to drive your online sales with high performance."},{"title":"Performance Optimization","description":"Auditing and upgrading your platform to achieve blazing fast load times."},{"title":"Ongoing Maintenance","description":"Constant monitoring, updating, and feature deployment without downtime."}]'::jsonb, 'code', 'Website Development Services', 'A professional, secure online presence — from a simple starter site to a full digital platform.', true, true, true, 1, CURRENT_TIMESTAMP) ON CONFLICT ("slug") DO NOTHING;
