INSERT INTO "services" ("id", "slug", "name", "summary", "heroTitle", "description", "bodyHeading", "bodyText", "sections", "iconKey", "seoTitle", "seoDescription", "showOnHomepage", "showInFooter", "isPublished", "sortOrder", "updatedAt") VALUES ('service-seo', 'seo', 'SEO', 'Strategies that deliver real traffic, leads, and sales — without the vanity metrics.', 'Be easier to find. Turn searches into enquiries.', 'VolTechAI helps businesses improve their organic visibility with technical, on-page and local SEO built around real commercial goals.', 'SEO that supports sustainable growth', 'We start with an audit, prioritise the changes most likely to help, and explain the work in plain English. Whether you need better foundations or ongoing support, we can shape the work around your business.', '[{"title":"Technical SEO","description":"Improve crawlability, site speed, mobile usability, indexing and structured data."},{"title":"On-page SEO","description":"Create clear page titles, headings, internal links and useful content aligned with customer intent."},{"title":"Local SEO","description":"Strengthen your visibility for relevant searches in East Ham, London and the areas you serve."},{"title":"SEO reporting","description":"Track rankings, organic visits and enquiries with straightforward reporting and recommendations."}]'::jsonb, 'search', 'SEO Services in London', 'Strategies that deliver real traffic, leads, and sales — without the vanity metrics.', true, true, true, 4, CURRENT_TIMESTAMP) ON CONFLICT ("slug") DO NOTHING;
