-- Defense in depth: these rules also apply to direct SQL writes.
ALTER TABLE "packages" ADD CONSTRAINT "package_checkout_rules" CHECK (NOT "purchasable" OR ("priceType" = 'FIXED' AND "billingType" = 'ONE_TIME' AND "amount" IS NOT NULL AND "amount" >= 30 AND "amount" <= 99999999 AND "currency" = 'gbp'));
ALTER TABLE "packages" ADD CONSTRAINT "package_amount_nonnegative" CHECK ("amount" IS NULL OR "amount" >= 0);
COMMIT;
